fn smallest_list_length(list: &Vec<Vec<i32>>) -> usize {
    // Since `list` is guaranteed to be non-empty, `min()` will return `Some(_)`.
    // We can safely unwrap it.
    list.iter()
        .map(|inner| inner.len())
        .min()
        .unwrap()
}

